#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr getRoomGraphics ();OSErr getRoomGraphics (){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	long		theWidth, theHeight, theSize;	OSErr		theError;	FSSpec		thePlugFSSpec;	char *theTexture;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------	// plug	theError = FSMakeFSSpec (0L, 0L, "\p:.256:dwar", &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	theWidth = 256;	theHeight = 256;	theSize = theWidth * theHeight;	FileSeek ( thePlugFileRef, 384L );	FileRead ( &thePalette, 2080L, thePlugFileRef );			theTexture = (char *) NewPtr ( theSize );	if ( theTexture == nil ){		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, 4072L );	FileRead ( theTexture, theSize, thePlugFileRef );	theError = writeBMP( "\p:Graphics.out:rooms.bmp", theWidth, theHeight, &thePalette, theTexture );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	return theError;}